sp_widget.css:
/* =========================================
   CFMS STUDENT DASHBOARD
   ========================================= */

.cfms-student-page {
    min-height: 100vh;

    background: #f0fbfc;

    color: #263238;

    font-family:
        "Segoe UI",
        Tahoma,
        Geneva,
        Verdana,
        sans-serif;
}


/* =========================================
   HEADER
   ========================================= */

.student-header {
    height: 72px;

    background: #00acc1;

    color: white;

    display: flex;

    align-items: center;

    justify-content: space-between;

    padding: 0 35px;

    box-sizing: border-box;
}


.student-brand {
    display: flex;

    align-items: center;

    gap: 12px;
}


.brand-icon {
    width: 43px;
    height: 43px;

    border-radius: 9px;

    background: white;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 22px;
}


.student-brand h2 {
    margin: 0;

    font-size: 23px;

    line-height: 1.1;
}


.student-brand span {
    font-size: 11px;

    opacity: 0.9;
}


/* USER */

.student-user {
    display: flex;

    align-items: center;

    gap: 10px;
}


.user-avatar {
    width: 38px;
    height: 38px;

    border-radius: 50%;

    background: white;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;
}


.user-info {
    display: flex;

    flex-direction: column;
}


.user-info strong {
    font-size: 14px;
}


.user-info span {
    font-size: 11px;

    opacity: 0.85;
}


.logout-btn {
    margin-left: 15px;

    padding: 8px 13px;

    border: 1px solid rgba(255,255,255,0.7);

    background: transparent;

    color: white;

    border-radius: 6px;

    cursor: pointer;
}


.logout-btn:hover {
    background: white;

    color: #00acc1;
}


/* =========================================
   LAYOUT
   ========================================= */

.student-layout {
    display: flex;

    min-height: calc(100vh - 72px);
}


/* =========================================
   SIDEBAR
   ========================================= */

.student-sidebar {
    width: 235px;

    flex-shrink: 0;

    background: white;

    border-right: 1px solid #dceff1;

    padding: 25px 15px;

    box-sizing: border-box;
}


.sidebar-title {
    padding: 0 12px 15px;

    color: #78909c;

    font-size: 11px;

    font-weight: 700;

    letter-spacing: 1px;
}


.sidebar-item {
    display: flex;

    align-items: center;

    gap: 13px;

    padding: 13px 14px;

    margin-bottom: 5px;

    border-radius: 8px;

    color: #546e7a !important;

    text-decoration: none !important;

    cursor: pointer;

    transition: 0.2s ease;
}


.sidebar-item i {
    width: 20px;

    text-align: center;

    font-size: 17px;
}


.sidebar-item:hover {
    background: #e0f7fa;

    color: #00acc1 !important;
}


.sidebar-item.active {
    background: #e0f7fa;

    color: #00acc1 !important;

    font-weight: 600;
}


.sidebar-divider {
    height: 1px;

    background: #e5eeee;

    margin: 20px 10px;
}


/* =========================================
   MAIN CONTENT
   ========================================= */

.student-content {
    flex: 1;

    padding: 35px 45px;

    box-sizing: border-box;

    max-width: 1400px;
}


/* =========================================
   WELCOME
   ========================================= */

.welcome-section {
    display: flex;

    align-items: center;

    justify-content: space-between;

    margin-bottom: 30px;
}


.page-label {
    color: #00acc1;

    font-size: 11px;

    font-weight: 700;

    letter-spacing: 1px;
}


.welcome-section h1 {
    margin: 7px 0;

    font-size: 31px;

    color: #263238;
}


.welcome-section p {
    margin: 0;

    color: #607d8b;

    font-size: 14px;
}


.quick-request-btn {
    background: #00acc1;

    color: white;

    border: none;

    border-radius: 8px;

    padding: 13px 20px;

    font-size: 14px;

    font-weight: 600;

    cursor: pointer;
}


.quick-request-btn:hover {
    background: #008fa1;
}


/* =========================================
   STATISTICS
   ========================================= */

.stats-container {
    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 18px;

    margin-bottom: 35px;
}


.stat-card {
    background: white;

    border-radius: 12px;

    padding: 20px;

    display: flex;

    align-items: center;

    gap: 15px;

    box-shadow:
        0 3px 15px rgba(0,0,0,0.05);

    border: 1px solid #e3f1f3;
}


.stat-icon {
    width: 50px;
    height: 50px;

    border-radius: 10px;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 21px;
}


.stat-icon.teal {
    background: #e0f7fa;

    color: #00acc1;
}


.stat-icon.blue {
    background: #e3f2fd;

    color: #1976d2;
}


.stat-icon.green {
    background: #e8f5e9;

    color: #43a047;
}


.stat-icon.orange {
    background: #fff3e0;

    color: #fb8c00;
}


.stat-details {
    display: flex;

    flex-direction: column;

    gap: 4px;
}


.stat-details span {
    color: #78909c;

    font-size: 12px;
}


.stat-details strong {
    color: #263238;

    font-size: 25px;
}


/* =========================================
   DASHBOARD SECTIONS
   ========================================= */

.dashboard-section {
    margin-bottom: 35px;
}


.section-heading {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 18px;
}


.section-heading h2 {
    margin: 0 0 5px;

    font-size: 21px;

    color: #263238;
}


.section-heading p {
    margin: 0;

    color: #78909c;

    font-size: 13px;
}


/* =========================================
   ACTION CARDS
   ========================================= */

.action-grid {
    display: grid;

    grid-template-columns:
        repeat(3, 1fr);

    gap: 20px;
}


.action-card {
    background: white;

    padding: 25px;

    border-radius: 13px;

    border: 1px solid #e1eff1;

    cursor: pointer;

    transition: all 0.25s ease;
}


.action-card:hover {
    transform: translateY(-5px);

    box-shadow:
        0 10px 25px rgba(0,0,0,0.08);

    border-color: #b2ebf2;
}


.action-icon {
    width: 48px;
    height: 48px;

    border-radius: 10px;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 20px;

    margin-bottom: 15px;
}


.teal-bg {
    background: #e0f7fa;

    color: #00acc1;
}


.blue-bg {
    background: #e3f2fd;

    color: #1976d2;
}


.orange-bg {
    background: #fff3e0;

    color: #fb8c00;
}


.action-card h3 {
    margin: 0 0 8px;

    color: #263238;

    font-size: 17px;
}


.action-card p {
    margin: 0 0 17px;

    color: #607d8b;

    font-size: 13px;

    line-height: 1.6;
}


.action-link {
    color: #00acc1;

    font-size: 13px;

    font-weight: 600;
}


/* =========================================
   VIEW ALL
   ========================================= */

.view-all-btn {
    border: none;

    background: transparent;

    color: #00acc1;

    font-size: 13px;

    font-weight: 600;

    cursor: pointer;
}


/* =========================================
   EMPTY STATE
   ========================================= */

.empty-state {
    background: white;

    border-radius: 13px;

    padding: 45px 20px;

    text-align: center;

    border: 1px solid #e1eff1;
}


.empty-icon {
    width: 60px;
    height: 60px;

    margin: 0 auto 15px;

    border-radius: 50%;

    background: #e0f7fa;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 25px;
}


.empty-state h3 {
    margin: 0 0 7px;

    color: #263238;
}


.empty-state p {
    color: #78909c;

    font-size: 13px;
}


.empty-btn {
    margin-top: 10px;

    padding: 10px 17px;

    border: none;

    border-radius: 7px;

    background: #00acc1;

    color: white;

    cursor: pointer;
}


/* =========================================
   REQUEST LIST
   ========================================= */

.request-list {
    background: white;

    border-radius: 13px;

    border: 1px solid #e1eff1;

    overflow: hidden;
}


.request-row {
    display: flex;

    align-items: center;

    justify-content: space-between;

    padding: 17px 20px;

    border-bottom: 1px solid #edf4f5;
}


.request-row:last-child {
    border-bottom: none;
}


.request-main {
    display: flex;

    align-items: center;

    gap: 13px;
}


.request-icon {
    width: 40px;
    height: 40px;

    border-radius: 8px;

    background: #e0f7fa;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;
}


.request-main h4 {
    margin: 0 0 3px;

    font-size: 14px;

    color: #263238;
}


.request-main p {
    margin: 0;

    font-size: 12px;

    color: #78909c;
}


.status-badge {
    padding: 6px 10px;

    border-radius: 20px;

    font-size: 11px;

    background: #e0f7fa;

    color: #008fa1;
}


/* =========================================
   HELP
   ========================================= */

.help-card {
    display: flex;

    align-items: center;

    gap: 20px;

    padding: 22px;

    border-radius: 12px;

    background: #4dd0e1;

    margin-bottom: 20px;
}


.help-icon {
    width: 45px;
    height: 45px;

    border-radius: 50%;

    background: white;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;

    flex-shrink: 0;
}


.help-content {
    flex: 1;
}


.help-content h3 {
    margin: 0 0 5px;

    color: #263238;
}


.help-content p {
    margin: 0;

    color: #37474f;

    font-size: 13px;
}


.help-btn {
    background: #00acc1;

    color: white;

    border: none;

    padding: 10px 17px;

    border-radius: 7px;

    cursor: pointer;

    font-weight: 600;
}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 1100px) {

    .stats-container {
        grid-template-columns:
            repeat(2, 1fr);
    }

    .action-grid {
        grid-template-columns:
            repeat(2, 1fr);
    }

}


@media (max-width: 800px) {

    .student-sidebar {
        width: 70px;

        padding: 20px 8px;
    }

    .sidebar-title,
    .sidebar-item span {
        display: none;
    }

    .sidebar-item {
        justify-content: center;
    }

    .student-content {
        padding: 25px;
    }

}


@media (max-width: 600px) {

    .student-header {
        height: auto;

        padding: 15px 18px;
    }

    .student-brand span,
    .user-info {
        display: none;
    }

    .logout-btn {
        margin-left: 5px;
    }

    .welcome-section {
        flex-direction: column;

        align-items: flex-start;

        gap: 20px;
    }

    .stats-container,
    .action-grid {
        grid-template-columns: 1fr;
    }

    .student-content {
        padding: 20px 15px;
    }

    .help-card {
        flex-direction: column;

        text-align: center;
    }

}

sp_widget.script:
(function() {

    /*
     * =========================================
     * DEFAULT DATA
     * =========================================
     */

    data.userName = gs.getUserDisplayName();

    data.totalRequests = 0;

    data.activeRequests = 0;

    data.resolvedRequests = 0;

    data.feedbackCount = 0;

    data.recentRequests = [];


    /*
     * =========================================
     * SECURITY CHECK
     * =========================================
     */

    if (!gs.isLoggedIn()) {

        data.redirect = "cfms_login";

        return;

    }


    /*
     * =========================================
     * STUDENT ROLE CHECK
     * =========================================
     */

    if (!gs.hasRole("cfms_student") &&
        !gs.hasRole("admin")) {

        data.redirect = "cfms_home";

        return;

    }


    /*
     * =========================================
     * STUDENT REQUESTS
     *
     * Recommended table:
     * incident
     *
     * caller_id = logged-in student
     * =========================================
     */

    var requestGR = new GlideRecord("incident");

    requestGR.addQuery(
        "caller_id",
        gs.getUserID()
    );

    requestGR.orderByDesc("sys_created_on");

    requestGR.query();


    while (requestGR.next()) {

        data.totalRequests++;


        /*
         * Resolved
         */

        if (requestGR.state == 6 ||
            requestGR.state == 7) {

            data.resolvedRequests++;

        } else {

            data.activeRequests++;

        }


        /*
         * Recent 5 requests
         */

        if (data.recentRequests.length < 5) {

            var stateText =
                requestGR.getDisplayValue("state");

            var statusClass =
                "status-active";


            if (requestGR.state == 6 ||
                requestGR.state == 7) {

                statusClass =
                    "status-resolved";

            }


            data.recentRequests.push({

                number:
                    requestGR.getValue("number"),

                short_description:
                    requestGR.getValue(
                        "short_description"
                    ),

                state:
                    stateText,

                statusClass:
                    statusClass

            });

        }

    }


    /*
     * =========================================
     * FEEDBACK COUNT
     *
     * Recommended custom table:
     * u_cfms_feedback
     * =========================================
     */

    if (GlideTableDescriptor
        .isValid("u_cfms_feedback")) {

        var feedbackGR =
            new GlideRecord(
                "u_cfms_feedback"
            );

        feedbackGR.addQuery(
            "u_student",
            gs.getUserID()
        );

        feedbackGR.query();

        data.feedbackCount =
            feedbackGR.getRowCount();

    }


})();
